using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace Enterprise.BusinessObjectGenerator
{
	public class AutoAddInfoBusinessObjectValidation : AutoBusinessObjectValidation
	{
		public AutoAddInfoBusinessObjectValidation(BusinessObjectInfo info, AutoPropertyList autoProperties)
			: base(info, autoProperties)
		{
		}

		#region Code for Body

		protected override string Body
		{
			get
			{
				return LinesOfCode(
					UsingClause,
					"",
					"namespace " + Info.Namespace,
					"{",
					"	[" + AutoGeneratedCodeAttribute + "]",
					"	public abstract class " + ClassName + " : " + Info.BaseValidationClassName,
					"	{",
					CodeForConstructor,
					"",
					CodeForAutoValidationType,
					"",
					CodeForPropertyValidation,
					"",
					CodeForValidateAll,
					"",
					CodeForImplementation + CodeForOldPrefix,
					"	}",
					"}"
					);
			}
		}

		#endregion

		#region Code for CodeForValidateAll

		protected override string CodeForValidateAll
		{
			get
			{
				var callValidateMethods = AutoProperties.CodeForCallingEachPropertyValidate(4);

				return LinesOfCode(
					"		#region Validate All",
					"",
					"		public override void ValidateAll()",
					"		{",
					"			base.ValidateAll();",
					"			using (ParentListInternals.SuspendListChanged())",
					"			{",
					callValidateMethods,
					"			}",
					"		}",
					"",
					"		#endregion");
			}
		}

		#endregion

		#region Code for Validation

		protected override string CodeForPropertyValidation
		{
			get
			{
				var result = LinesOfCode(
					"		#region Properties",
					"",
					"");

				foreach (var property in ApplicableProperties)
				{
					if (property.GenerateValidation)
					{
						result += CodeForValidation(property);
					}
				}

				result += "		#endregion";

				return result;
			}
		}

		#endregion

		#region Code for Implementation

		public override string CodeForImplementation
		{
			get
			{
				return LinesOfCode(
					"		#region Implementation",
					"",
					"		protected new readonly " + Info.ClassNames.BusinessObjectAuto + " Parent;",
					"		private readonly ISingleElementListInternal ParentListInternals;",
					"		private readonly IValidationInternals ZValidationInternals;",
					"",
					"		#endregion");
			}
		}

		#endregion

		#region CodeForOldPrefix

		string CodeForOldPrefix
		{
			get
			{
				var stringBuilder = new StringBuilder();
				if (!string.IsNullOrEmpty(Info.OldPrefix))
				{
					stringBuilder.Append(@"

		#region Properties with Old Prefix
");
					foreach (var property in ApplicableProperties)
					{
						var fieldName = property.ColumnName.Substring(property.ColumnName.IndexOf("_") + 1);
						var fieldNameWithPrefix = $"{Info.OldPrefix}_{fieldName}";

						stringBuilder.Append($@"
		public void Validate{fieldNameWithPrefix}()
		{{
			ZValidationInternals.Validate(Parent.{property.ColumnName}Info, Get{property.ColumnName}ValidationInvoker());
		}}
");
					}

					stringBuilder.Append(@"
		#endregion");
				}
				return stringBuilder.ToString();
			}
		}

		#endregion

		IEnumerable<AutoProperty> ApplicableProperties => AutoProperties.Properties.Where(property => !property.ColumnName.Contains(CargoWise.Schema.Schema.ClusterKeyColumnSuffix));

		new AddInfoBusinessObjectInfo Info => (AddInfoBusinessObjectInfo)base.Info;
	}
}
